int main(void)
{
    uint8_t inputs;
    uint8_t prev_inputs = 0U;
    uint32_t last_blink_tick = 0U;

    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_USART2_UART_Init();
    tim3_init_2khz();

    sensorhub_gpio_bus_init();
    actuator_edr_gpio_bus_init();
    sensorhub_release_all_cs();
    actuator_edr_release_all_cs();
    squib_send_command(SQUIB_CMD_ALL_OFF);

    uart_puts("\r\n");
    uart_puts("========================================\r\n");
    uart_puts("ACU_LADA Proteus scaffold v1.0\r\n");
    uart_puts("SensorHub: IMU + HighG + KP200 virtual register model\r\n");
    uart_puts("Actuator: squib outputs only, EDR path removed from this bench stage\r\n");
    uart_puts("STM32 transport: software SPI on both buses, HSI system clock\r\n");
    uart_puts("Scenarios: 0 idle, 1 front, 2 side_L, 3 side_R, 4 rear, 5 rollover, 6 misuse, 7 visual\r\n");
    uart_puts("========================================\r\n");

    inputs = read_scenario_inputs_stm32();
    (void)perform_startup_selftest(inputs);
    prev_inputs = inputs;
    g_processed_tick_2khz = g_tick_2khz_counter;
    last_blink_tick = HAL_GetTick();

    while (1) {
        uint32_t current_tick_2khz = g_tick_2khz_counter;
        uint32_t now = HAL_GetTick();
        uint8_t start_edge;
        uint8_t reset_edge;
        uint8_t scenario;

        inputs = read_scenario_inputs_stm32();
        scenario = (uint8_t)(inputs & INPUT_SCENARIO_MASK);
        start_edge = ((inputs & INPUT_START_BIT) != 0U) && ((prev_inputs & INPUT_START_BIT) == 0U);
        reset_edge = ((inputs & INPUT_RESET_BIT) != 0U) && ((prev_inputs & INPUT_RESET_BIT) == 0U);

        if ((now - last_blink_tick) >= 500U) {
            HAL_GPIO_TogglePin(LED_TICK_GPIO_Port, LED_TICK_Pin);
            last_blink_tick = now;
        }

        if (reset_edge) {
            uart_puts("[RESET] Restarting ACU self-test...\r\n");
            (void)perform_startup_selftest(inputs);
            prev_inputs = inputs;
            g_processed_tick_2khz = g_tick_2khz_counter;
            continue;
        }

        if ((inputs & INPUT_FAULT_BIT) != 0U && g_state != ACU_STATE_FAULT) {
            enter_fault_state(inputs, 0x00, "TEST_FAULT input active");
        }

        switch (g_state) {
        case ACU_STATE_READY:
            if (start_edge) {
                if (scenario == SCENARIO_VISUAL) {
                    uart_puts("[VISUAL] Running actuator visual sequence...\r\n");
                    test_squib_visual();
                    g_last_event = CRASH_EVENT_VISUAL;
                    g_last_squib_cmd = SQUIB_CMD_ALL_OFF;
                    g_state = ACU_STATE_LOCKED;
                    led_set_locked_state();
                    uart_puts("[VISUAL] Sequence complete. Press RESET for a new run.\r\n");
                } else {
                    decision_reset(&g_decision);
                    g_monitor_scenario = scenario;
                    g_monitor_start_tick_2khz = g_tick_2khz_counter;
                    g_processed_tick_2khz = g_monitor_start_tick_2khz;
                    g_impact_onset_tick_2khz = 0U;
                    g_impact_seen = 0U;
                    g_state = ACU_STATE_MONITOR;
                    led_set_monitor_state();
                    uart_printf("[MONITOR] Scenario %u (%s), sampling at 2 kHz\r\n",
                                scenario, scenario_name(scenario));
                }
            }
            break;

        case ACU_STATE_MONITOR:
            if ((inputs & INPUT_START_BIT) == 0U) {
                g_state = ACU_STATE_READY;
                decision_reset(&g_decision);
                led_set_ready_state();
                uart_puts("[MONITOR] Start released. Back to READY.\r\n");
                break;
            }

            if (current_tick_2khz != g_processed_tick_2khz) {
                uint32_t diff = current_tick_2khz - g_processed_tick_2khz;

                if (diff > 1U) {
                    g_tick_2khz_missed += (diff - 1U);
                }

                while ((g_processed_tick_2khz != current_tick_2khz) && (g_state == ACU_STATE_MONITOR)) {
                    sensor_snapshot_t snapshot;
                    crash_event_t event;
                    uint8_t squib_mask;

                    g_processed_tick_2khz++;

                    if (!sample_all_sensors(&snapshot)) {
                        enter_fault_state(inputs, 0x00, "Sensor read transaction failed");
                        break;
                    }

                    if (snapshot.flags != SENSOR_FLAG_ALL) {
                        enter_fault_state(inputs, snapshot.flags, "Sensor validity check failed");
                        break;
                    }

                    if (!g_impact_seen && scenario_activity_detected(g_monitor_scenario, &snapshot)) {
                        char onset_buf[24];
                        g_impact_seen = 1U;
                        g_impact_onset_tick_2khz = g_processed_tick_2khz;
                        format_ticks_ms(g_impact_onset_tick_2khz - g_monitor_start_tick_2khz,
                                        onset_buf, sizeof(onset_buf));
                        uart_printf("[IMPACT] onset at +%s ms from START\r\n", onset_buf);
                    }

                    event = evaluate_event(&snapshot, &g_decision, TICK_DT_S);
                    if (event != CRASH_EVENT_NONE) {
                        char start_buf[24];
                        char onset_buf[24];

                        squib_mask = event_to_squib_mask(event);
                        squib_send_command(squib_mask);
                        g_last_squib_cmd = squib_mask;
                        g_last_event = event;
                        g_deploy_timestamp = g_processed_tick_2khz;
                        g_state = ACU_STATE_DEPLOYED;
                        led_set_deployed_state();

                        format_ticks_ms(g_deploy_timestamp - g_monitor_start_tick_2khz,
                                        start_buf, sizeof(start_buf));
                        if (g_impact_seen) {
                            format_ticks_ms(g_deploy_timestamp - g_impact_onset_tick_2khz,
                                            onset_buf, sizeof(onset_buf));
                        } else {
                            strcpy(onset_buf, "n/a");
                        }

                        uart_printf("[DEPLOY] %s -> squib mask 0x%02X, t_start=%s ms, t_impact=%s ms\r\n",
                                    event_name(event), squib_mask, start_buf, onset_buf);
                        print_decision_metrics(event, &g_decision);
                    }
                }
            }
            break;

        case ACU_STATE_DEPLOYED:
            if ((current_tick_2khz - g_deploy_timestamp) >= DEPLOY_HOLD_TICKS) {
                g_state = ACU_STATE_LOCKED;
                led_set_locked_state();
                uart_puts("[LOCKED] Outputs latched. Press RESET for next run.\r\n");
            }
            break;

        case ACU_STATE_LOCKED:
            /* Latched until external reset input. */
            break;

        case ACU_STATE_FAULT:
            /* Fault remains latched until external reset input. */
            break;

        case ACU_STATE_BOOT:
        case ACU_STATE_SELFTEST:
        default:
            break;
        }

        prev_inputs = inputs;
        HAL_Delay(2);
    }
}

static void uart_puts(const char *s)
{
    HAL_UART_Transmit(&huart2, (uint8_t *)s, (uint16_t)strlen(s), HAL_MAX_DELAY);
}

static void uart_printf(const char *fmt, ...)
{
    char buffer[224];
    va_list args;

    va_start(args, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt, args);
    va_end(args);

    uart_puts(buffer);
}

static float f_abs(float value)
{
    return (value < 0.0f) ? -value : value;
}

static int8_t sign_with_deadband(float value, float deadband)
{
    if (value > deadband) {
        return 1;
    }
    if (value < -deadband) {
        return -1;
    }
    return 0;
}

static int16_t le16_to_s16(const uint8_t *buf)
{
    return (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
}

static int16_t be16_to_s16(const uint8_t *buf)
{
    return (int16_t)(((uint16_t)buf[0] << 8) | (uint16_t)buf[1]);
}

static void format_ticks_ms(uint32_t ticks, char *buffer, uint32_t buffer_size)
{
    snprintf(buffer, buffer_size, "%lu.%01lu",
             (unsigned long)(ticks / 2U),
             (unsigned long)((ticks & 1U) ? 5U : 0U));
}

static void led_all_off(void)
{
    HAL_GPIO_WritePin(GPIOD,
                      LED_READY_Pin | LED_ARMED_Pin | LED_CRASH_Pin | LED_LOCKED_Pin |
                      LED_SENSOR_OK_Pin | LED_EDR_Pin | LED_TICK_Pin | LED_FAULT_Pin,
                      GPIO_PIN_RESET);
}

static void led_set_ready_state(void)
{
    led_all_off();
    HAL_GPIO_WritePin(LED_READY_GPIO_Port, LED_READY_Pin, GPIO_PIN_SET);
    HAL_GPIO_WritePin(LED_SENSOR_OK_GPIO_Port, LED_SENSOR_OK_Pin, GPIO_PIN_SET);
}

static void led_set_monitor_state(void)
{
    led_set_ready_state();
    HAL_GPIO_WritePin(LED_ARMED_GPIO_Port, LED_ARMED_Pin, GPIO_PIN_SET);
}

static void led_set_deployed_state(void)
{
    led_set_monitor_state();
    HAL_GPIO_WritePin(LED_CRASH_GPIO_Port, LED_CRASH_Pin, GPIO_PIN_SET);
}

static void led_set_locked_state(void)
{
    led_set_ready_state();
    HAL_GPIO_WritePin(LED_LOCKED_GPIO_Port, LED_LOCKED_Pin, GPIO_PIN_SET);
    HAL_GPIO_WritePin(LED_CRASH_GPIO_Port, LED_CRASH_Pin, GPIO_PIN_SET);
    HAL_GPIO_WritePin(LED_ARMED_GPIO_Port, LED_ARMED_Pin, GPIO_PIN_RESET);
}

static void led_set_fault_state(void)
{
    led_all_off();
    HAL_GPIO_WritePin(LED_FAULT_GPIO_Port, LED_FAULT_Pin, GPIO_PIN_SET);
}

static uint8_t read_scenario_inputs_stm32(void)
{
    uint8_t value = 0;

    if (HAL_GPIO_ReadPin(TEST0_GPIO_Port, TEST0_Pin) == GPIO_PIN_SET) value |= (1U << 0);
    if (HAL_GPIO_ReadPin(TEST1_GPIO_Port, TEST1_Pin) == GPIO_PIN_SET) value |= (1U << 1);
    if (HAL_GPIO_ReadPin(TEST2_GPIO_Port, TEST2_Pin) == GPIO_PIN_SET) value |= (1U << 2);
    if (HAL_GPIO_ReadPin(TEST_START_GPIO_Port, TEST_START_Pin) == GPIO_PIN_SET) value |= (1U << 3);
    if (HAL_GPIO_ReadPin(TEST_RESET_GPIO_Port, TEST_RESET_Pin) == GPIO_PIN_SET) value |= (1U << 4);
    if (HAL_GPIO_ReadPin(TEST_FAULT_GPIO_Port, TEST_FAULT_Pin) == GPIO_PIN_SET) value |= (1U << 5);

    return value;
}

static const char *scenario_name(uint8_t scenario)
{
    switch (scenario & INPUT_SCENARIO_MASK) {
    case SCENARIO_IDLE: return "idle";
    case SCENARIO_FRONT: return "front";
    case SCENARIO_SIDE_LEFT: return "side_left";
    case SCENARIO_SIDE_RIGHT: return "side_right";
    case SCENARIO_REAR: return "rear";
    case SCENARIO_ROLLOVER: return "rollover";
    case SCENARIO_MISUSE: return "misuse";
    case SCENARIO_VISUAL: return "visual";
    default: return "unknown";
    }
}

static uint8_t scenario_activity_detected(uint8_t scenario, const sensor_snapshot_t *snapshot)
{
    switch (scenario & INPUT_SCENARIO_MASK) {
    case SCENARIO_FRONT:
        return snapshot->imu.ax <= -FRONT_ONSET_TH_MS2;
    case SCENARIO_SIDE_LEFT:
        return (snapshot->imu.ay >= SIDE_ONSET_TH_MS2) || (snapshot->kp200_l.dp_kpa > 0.5f);
    case SCENARIO_SIDE_RIGHT:
        return (snapshot->imu.ay <= -SIDE_ONSET_TH_MS2) || (snapshot->kp200_r.dp_kpa > 0.5f);
    case SCENARIO_REAR:
        return snapshot->imu.ax >= REAR_ONSET_TH_MS2;
    case SCENARIO_ROLLOVER:
        return f_abs(snapshot->imu.gx) >= ROLLOVER_ONSET_DPS;
    case SCENARIO_MISUSE:
        return (f_abs(snapshot->imu.ax) >= FRONT_ONSET_TH_MS2) ||
               (f_abs(snapshot->imu.ay) >= SIDE_ONSET_TH_MS2) ||
               (f_abs(snapshot->imu.gx) >= ROLLOVER_ONSET_DPS);
    default:
        return 0U;
    }
}

static void soft_spi_delay_cycles(uint32_t cycles)
{
    volatile uint32_t i;

    for (i = 0; i < cycles; i++) {
        __NOP();
    }
}

static void soft_spi_edge_delay(void)
{
    soft_spi_delay_cycles(60U);
}

static void soft_spi_select_delay(void)
{
    soft_spi_delay_cycles(400U);
}

static void soft_spi_interbyte_delay(void)
{
    soft_spi_delay_cycles(2400U);
}

static uint8_t soft_spi_transfer_byte(const soft_spi_bus_t *bus, uint8_t tx)
{
    uint8_t rx = 0;
    uint8_t bit;

    for (bit = 0; bit < 8U; bit++) {
        HAL_GPIO_WritePin(bus->mosi_port, bus->mosi_pin,
                          (tx & 0x80U) ? GPIO_PIN_SET : GPIO_PIN_RESET);
        soft_spi_edge_delay();

        HAL_GPIO_WritePin(bus->sck_port, bus->sck_pin, GPIO_PIN_SET);
        soft_spi_edge_delay();

        rx <<= 1;
        if (HAL_GPIO_ReadPin(bus->miso_port, bus->miso_pin) == GPIO_PIN_SET) {
            rx |= 0x01U;
        }

        HAL_GPIO_WritePin(bus->sck_port, bus->sck_pin, GPIO_PIN_RESET);
        tx <<= 1;
        soft_spi_edge_delay();
    }

    HAL_GPIO_WritePin(bus->mosi_port, bus->mosi_pin, GPIO_PIN_RESET);
    return rx;
}

