static void actuator_edr_release_all_cs(void)
{
    HAL_GPIO_WritePin(CS_SQUIB_GPIO_Port, CS_SQUIB_Pin, GPIO_PIN_SET);
    HAL_GPIO_WritePin(EDR_CS_GPIO_Port, EDR_CS_Pin, GPIO_PIN_SET);
}

static void actuator_edr_begin_squib(void)
{
    actuator_edr_release_all_cs();
    soft_spi_select_delay();
    HAL_GPIO_WritePin(CS_SQUIB_GPIO_Port, CS_SQUIB_Pin, GPIO_PIN_RESET);
    soft_spi_select_delay();
}

static void actuator_edr_begin_edr(void)
{
    actuator_edr_release_all_cs();
    soft_spi_select_delay();
    HAL_GPIO_WritePin(EDR_CS_GPIO_Port, EDR_CS_Pin, GPIO_PIN_RESET);
    soft_spi_select_delay();
}

static void actuator_edr_end_transaction(GPIO_TypeDef *cs_port, uint16_t cs_pin)
{
    soft_spi_select_delay();
    HAL_GPIO_WritePin(cs_port, cs_pin, GPIO_PIN_SET);
    HAL_GPIO_WritePin(g_actuator_edr_bus.sck_port, g_actuator_edr_bus.sck_pin, GPIO_PIN_RESET);
    soft_spi_select_delay();
}

static void squib_send_command(uint8_t cmd)
{
    actuator_edr_begin_squib();
    (void)soft_spi_transfer_byte(&g_actuator_edr_bus, cmd);
    actuator_edr_end_transaction(CS_SQUIB_GPIO_Port, CS_SQUIB_Pin);
}

static void test_squib_visual(void)
{
    squib_send_command(SQUIB_CMD_ALL_OFF);
    uart_puts("    VISUAL CMD ALL_OFF\r\n");
    HAL_Delay(200);

    squib_send_command(SQUIB_MASK_FRONT);
    uart_puts("    VISUAL CMD FRONT\r\n");
    HAL_Delay(250);

    squib_send_command(SQUIB_MASK_BELT);
    uart_puts("    VISUAL CMD BELT\r\n");
    HAL_Delay(250);

    squib_send_command(SQUIB_MASK_SIDE_L);
    uart_puts("    VISUAL CMD SIDE_L\r\n");
    HAL_Delay(250);

    squib_send_command(SQUIB_MASK_SIDE_R);
    uart_puts("    VISUAL CMD SIDE_R\r\n");
    HAL_Delay(250);

    squib_send_command(SQUIB_MASK_ROLLOVER);
    uart_puts("    VISUAL CMD ROLLOVER\r\n");
    HAL_Delay(250);

    squib_send_command(SQUIB_CMD_ALL_ON);
    uart_puts("    VISUAL CMD ALL_ON\r\n");
    HAL_Delay(600);

    squib_send_command(SQUIB_CMD_ALL_OFF);
    uart_puts("    VISUAL CMD ALL_OFF\r\n");
}

static void edr_write_reg(uint8_t addr, uint8_t value)
{
    actuator_edr_begin_edr();
    (void)soft_spi_transfer_byte(&g_actuator_edr_bus, (uint8_t)(addr & 0x7FU));
    soft_spi_interbyte_delay();
    (void)soft_spi_transfer_byte(&g_actuator_edr_bus, value);
    actuator_edr_end_transaction(EDR_CS_GPIO_Port, EDR_CS_Pin);
}

static uint8_t edr_read_reg(uint8_t addr)
{
    uint8_t value;

    actuator_edr_begin_edr();
    (void)soft_spi_transfer_byte(&g_actuator_edr_bus, (uint8_t)(SENSOR_PROTO_READ_BIT | (addr & 0x7FU)));
    soft_spi_interbyte_delay();
    value = soft_spi_transfer_byte(&g_actuator_edr_bus, 0x00);
    actuator_edr_end_transaction(EDR_CS_GPIO_Port, EDR_CS_Pin);

    return value;
}

static uint8_t edr_test_link(void)
{
    uint8_t who = edr_read_reg(EDR_REG_WHO_AM_I);
    uint8_t fault = edr_read_reg(EDR_REG_FAULT);

    uart_puts("[SELFTEST] EDR link...\r\n");
    if (who != EDR_WHO_AM_I) {
        uart_printf("    EDR WHO=0x%02X EXPECTED=0x%02X FAIL\r\n", who, EDR_WHO_AM_I);
        return 0U;
    }

    if (fault != 0x00U) {
        uart_printf("    EDR FAULT=0x%02X FAIL\r\n", fault);
        return 0U;
    }

    uart_printf("    EDR WHO=0x%02X OK\r\n", who);
    return 1U;
}

static void edr_clear_log(void)
{
    edr_write_reg(EDR_REG_CTRL, EDR_CTRL_CLEAR_STATUS | EDR_CTRL_CLEAR_LOG);
}

static void edr_log_boot(uint8_t scenario_inputs)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_BOOT);
    edr_write_reg(EDR_REG_SCENARIO_INPUTS, scenario_inputs);
    edr_write_reg(EDR_REG_SENSOR_FLAGS, 0x00);
    edr_write_reg(EDR_REG_HOST_EVENT_ID, EDR_HOST_EVENT_BOOT);
    edr_write_reg(EDR_REG_HOST_FLAGS, 0x00);
    edr_write_reg(EDR_REG_HOST_DATA0, 0x01);
    edr_write_reg(EDR_REG_HOST_DATA1, scenario_inputs & INPUT_SCENARIO_MASK);
}

static void edr_log_selftest_ok(void)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_SELFTEST);
    edr_write_reg(EDR_REG_SENSOR_FLAGS, SENSOR_FLAG_ALL);
    edr_write_reg(EDR_REG_HOST_EVENT_ID, EDR_HOST_EVENT_SELFTEST_OK);
    edr_write_reg(EDR_REG_HOST_FLAGS, EDR_HOST_FLAG_SENSOR_OK);
    edr_write_reg(EDR_REG_HOST_DATA0, SENSOR_FLAG_ALL);
    edr_write_reg(EDR_REG_HOST_DATA1, 0x00);
}

static void edr_log_ready(void)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_READY);
}

static void edr_log_monitor(uint8_t scenario_inputs, uint8_t sensor_flags)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_MONITOR);
    edr_write_reg(EDR_REG_SCENARIO_INPUTS, scenario_inputs);
    edr_write_reg(EDR_REG_SENSOR_FLAGS, sensor_flags);
}

static void edr_log_deploy(crash_event_t event, uint8_t squib_mask, uint8_t scenario_inputs, uint8_t sensor_flags)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_DEPLOYED);
    edr_write_reg(EDR_REG_SCENARIO_INPUTS, scenario_inputs);
    edr_write_reg(EDR_REG_SENSOR_FLAGS, sensor_flags);
    edr_write_reg(EDR_REG_HOST_EVENT_ID, event_to_edr_host_id(event));
    edr_write_reg(EDR_REG_HOST_FLAGS, EDR_HOST_FLAG_SENSOR_OK | EDR_HOST_FLAG_DEPLOYED);
    edr_write_reg(EDR_REG_HOST_DATA0, squib_mask);
    edr_write_reg(EDR_REG_HOST_DATA1, (uint8_t)(scenario_inputs & INPUT_SCENARIO_MASK));
}

static void edr_log_visual_complete(void)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_VISUAL);
    edr_write_reg(EDR_REG_HOST_EVENT_ID, EDR_HOST_EVENT_VISUAL);
    edr_write_reg(EDR_REG_HOST_FLAGS, EDR_HOST_FLAG_VISUAL_DONE);
    edr_write_reg(EDR_REG_HOST_DATA0, SQUIB_CMD_ALL_ON);
    edr_write_reg(EDR_REG_HOST_DATA1, SQUIB_CMD_ALL_OFF);
}

static void edr_log_fault(uint8_t scenario_inputs, uint8_t sensor_flags)
{
    edr_write_reg(EDR_REG_STAGE, EDR_STAGE_FAULT);
    edr_write_reg(EDR_REG_SCENARIO_INPUTS, scenario_inputs);
    edr_write_reg(EDR_REG_SENSOR_FLAGS, sensor_flags);
    edr_write_reg(EDR_REG_HOST_EVENT_ID, EDR_HOST_EVENT_FAULT);
    edr_write_reg(EDR_REG_HOST_FLAGS, EDR_HOST_FLAG_FAULT);
    edr_write_reg(EDR_REG_HOST_DATA0, sensor_flags);
    edr_write_reg(EDR_REG_HOST_DATA1, (uint8_t)(scenario_inputs & INPUT_SCENARIO_MASK));
}

static void edr_dump_summary(void)
{
    uint8_t who = edr_read_reg(EDR_REG_WHO_AM_I);
    uint8_t status = edr_read_reg(EDR_REG_STATUS);
    uint8_t stage = edr_read_reg(EDR_REG_STAGE);
    uint8_t scenario = edr_read_reg(EDR_REG_SCENARIO_INPUTS);
    uint8_t sensor_flags = edr_read_reg(EDR_REG_SENSOR_FLAGS);
    uint8_t last_cmd = edr_read_reg(EDR_REG_LAST_SQUIB_CMD);
    uint8_t output_mask = edr_read_reg(EDR_REG_SQUIB_OUTPUT_MASK);
    uint8_t fault = edr_read_reg(EDR_REG_FAULT);
    uint16_t transactions = ((uint16_t)edr_read_reg(EDR_REG_TRANSACTION_H) << 8) |
                            (uint16_t)edr_read_reg(EDR_REG_TRANSACTION_L);

    uart_printf("    EDR WHO=0x%02X STATUS=0x%02X STAGE=0x%02X\r\n", who, status, stage);
    uart_printf("    SCENARIO=0x%02X SENSOR_FLAGS=0x%02X\r\n", scenario, sensor_flags);
    uart_printf("    LAST_SQUIB_CMD=0x%02X OUTPUT_MASK=0x%02X\r\n", last_cmd, output_mask);
    uart_printf("    FAULT=0x%02X TX_COUNT=%u\r\n", fault, transactions);
    uart_printf("    TIM3_MISSED=%lu\r\n", (unsigned long)g_tick_2khz_missed);
}

static void tim3_init_2khz(void)
{
    __HAL_RCC_TIM3_CLK_ENABLE();

    TIM3->CR1 = 0x0000U;
    TIM3->PSC = 15U;
    TIM3->ARR = 499U;
    TIM3->CNT = 0U;
    TIM3->DIER |= TIM_DIER_UIE;
    TIM3->EGR |= TIM_EGR_UG;

    HAL_NVIC_SetPriority(TIM3_IRQn, 2, 0);
    HAL_NVIC_EnableIRQ(TIM3_IRQn);

    TIM3->CR1 |= TIM_CR1_CEN;
}

static uint8_t cross_validate_frontal(const sensor_snapshot_t *snapshot)
{
    uint8_t votes = 0U;

    if (snapshot->imu.ax <= -FRONT_IMU_TH_MS2) {
        votes++;
    }
    if (snapshot->highg_l.ax <= -FRONT_HIGHG_TH_MS2) {
        votes++;
    }
    if (snapshot->highg_r.ax <= -FRONT_HIGHG_TH_MS2) {
        votes++;
    }

    return votes >= 2U;
}

static uint8_t cross_validate_side_left(const sensor_snapshot_t *snapshot)
{
    return (snapshot->imu.ay >= SIDE_IMU_TH_MS2) &&
           (snapshot->highg_l.ay >= SIDE_HIGHG_TH_MS2) &&
           (snapshot->kp200_l.dp_kpa >= SIDE_PPS_TH_KPA);
}

static uint8_t cross_validate_side_right(const sensor_snapshot_t *snapshot)
{
    return (snapshot->imu.ay <= -SIDE_IMU_TH_MS2) &&
           (snapshot->highg_r.ay <= -SIDE_HIGHG_TH_MS2) &&
           (snapshot->kp200_r.dp_kpa >= SIDE_PPS_TH_KPA);
}

static uint8_t cross_validate_rear(const sensor_snapshot_t *snapshot)
{
    uint8_t votes = 0U;

    if (snapshot->imu.ax >= REAR_IMU_TH_MS2) {
        votes++;
    }
    if (snapshot->highg_l.ax >= REAR_HIGHG_TH_MS2) {
        votes++;
    }
    if (snapshot->highg_r.ax >= REAR_HIGHG_TH_MS2) {
        votes++;
    }

    return votes >= 2U;
}

static uint8_t cross_validate_rollover(const sensor_snapshot_t *snapshot)
{
    return (f_abs(snapshot->imu.gx) >= ROLLOVER_GX_TH_DPS) &&
           (f_abs(snapshot->imu.ay) >= ROLLOVER_AY_TH_MS2);
}

static void update_safing_gate(safing_gate_t *gate, float a_independent, float threshold_ms, float dt_s, float idle_threshold_ms2)
{
    if (f_abs(a_independent) >= idle_threshold_ms2) {
        gate->dv_ms += f_abs(a_independent) * dt_s;
        gate->window_ticks++;
        gate->idle_ticks = 0U;

        if (gate->window_ticks > SAFING_WINDOW_TICKS) {
            gate->dv_ms = 0.0f;
            gate->window_ticks = 1U;
        }

        if (gate->dv_ms >= threshold_ms) {
            gate->armed = 1U;
        }
    } else {
        gate->window_ticks = 0U;
        gate->dv_ms = 0.0f;

        if (gate->armed) {
            if (gate->idle_ticks < 0xFFFFU) {
                gate->idle_ticks++;
            }

            if (gate->idle_ticks >= SAFING_REARM_TICKS) {
                gate->armed = 0U;
                gate->idle_ticks = 0U;
            }
        }
    }
}

static void update_jerk_gate(jerk_gate_t *gate, float a_current, float dt_s, float energy_min, float energy_max, uint8_t active)
{
    float jerk;

    if (!active) {
        gate->energy = 0.0f;
        gate->samples = 0U;
        gate->initialized = 0U;
        gate->is_crash = 0U;
        gate->last_a = 0.0f;
        return;
    }

    if (!gate->initialized) {
        gate->last_a = a_current;
        gate->initialized = 1U;
        return;
    }

    jerk = (a_current - gate->last_a) / dt_s;
    gate->energy += jerk * jerk * dt_s;
    gate->last_a = a_current;
    gate->samples++;

    if (gate->samples >= JERK_WINDOW_TICKS) {
        if ((gate->energy >= energy_min) && (gate->energy <= energy_max)) {
            gate->is_crash = 1U;
        }
        gate->samples = 0U;
        gate->energy = 0.0f;
    }
}

static void update_oscillation_gate(osc_gate_t *gate, int8_t sign, uint8_t active)
{
    if (!active) {
        gate->last_sign = 0;
        gate->sign_changes = 0U;
        gate->samples = 0U;
        gate->is_oscillation = 0U;
        return;
    }

    if ((sign != 0) && (gate->last_sign != 0) && (sign != gate->last_sign)) {
        gate->sign_changes++;
    }

    if (sign != 0) {
        gate->last_sign = sign;
    }

    gate->samples++;
    if (gate->samples >= OSC_WINDOW_TICKS) {
        if (gate->sign_changes > OSC_SIGN_CHANGE_LIMIT) {
            gate->is_oscillation = 1U;
        }
        gate->samples = 0U;
        gate->sign_changes = 0U;
        gate->last_sign = sign;
    }
}

static void decision_reset(decision_state_t *state)
{
    memset(state, 0, sizeof(*state));
}

static crash_event_t evaluate_event(const sensor_snapshot_t *snapshot, decision_state_t *state, float dt_s)
{
    float decel_x = (snapshot->imu.ax < 0.0f) ? -snapshot->imu.ax : 0.0f;
    float accel_rear_x = (snapshot->imu.ax > 0.0f) ? snapshot->imu.ax : 0.0f;
    float accel_side_left_y = (snapshot->imu.ay > 0.0f) ? snapshot->imu.ay : 0.0f;
    float accel_side_right_y = (snapshot->imu.ay < 0.0f) ? -snapshot->imu.ay : 0.0f;
    float a_total_yz;
    float phi_acc_deg;
    float alpha_eff;
    float dphi_deg;
    float front_ds;
    float front_e_threshold;
    int8_t ax_sign = sign_with_deadband(snapshot->imu.ax, FRONT_ONSET_TH_MS2);
    int8_t ay_sign = sign_with_deadband(snapshot->imu.ay, SIDE_ONSET_TH_MS2);
    int8_t gx_sign = sign_with_deadband(snapshot->imu.gx, ROLLOVER_ONSET_DPS);
    uint8_t front_active = (snapshot->imu.ax <= -FRONT_ONSET_TH_MS2);
    uint8_t side_left_active = (snapshot->imu.ay >= SIDE_ONSET_TH_MS2) || (snapshot->kp200_l.dp_kpa > 0.5f);
    uint8_t side_right_active = (snapshot->imu.ay <= -SIDE_ONSET_TH_MS2) || (snapshot->kp200_r.dp_kpa > 0.5f);
    uint8_t rear_active = (snapshot->imu.ax >= REAR_ONSET_TH_MS2);
    uint8_t rollover_active = (f_abs(snapshot->imu.gx) >= ROLLOVER_ONSET_DPS);

    if (front_active) {
        state->front_duration_ticks++;
        update_safing_gate(&state->safing_front,
                           ((snapshot->highg_l.ax + snapshot->highg_r.ax) * -0.5f),
                           FRONT_DV_THRESHOLD_MS,
                           dt_s,
                           SAFING_IDLE_AX_MS2);
        update_jerk_gate(&state->jerk_front,
                         snapshot->imu.ax,
                         dt_s,
                         JERK_FRONT_MIN,
                         JERK_FRONT_MAX,
                         front_active);
        update_oscillation_gate(&state->osc_front, ax_sign, front_active);

        if (!state->front_red.started && (decel_x >= FRONT_RED_B_MS2)) {
            state->front_red.started = 1U;
            state->front_red.last_a_ms2 = decel_x;
        }

        if (state->front_red.started) {
            state->front_red.v_ms += 0.5f * (state->front_red.last_a_ms2 + decel_x) * dt_s;
            front_ds = state->front_red.v_ms * dt_s;
            state->front_red.s_m += front_ds;
            if (decel_x > FRONT_RED_B_MS2) {
                state->front_red.e_res += (decel_x - FRONT_RED_B_MS2) * front_ds;
            }
            state->front_red.last_a_ms2 = decel_x;

            if (state->front_red.s_m >= FRONT_RED_S0_M) {
                front_e_threshold = FRONT_RED_E0 + (FRONT_RED_SLOPE_M * (FRONT_RED_S0_M - state->front_red.s_m));
                if (state->front_red.e_res >= front_e_threshold) {
                    state->front_red.should_deploy = 1U;
                }
            }
        }

        if (cross_validate_frontal(snapshot)) {
            if (state->front_count < 0xFFU) {
                state->front_count++;
            }
        } else {
            state->front_count = 0U;
        }
    } else {
        state->front_duration_ticks = 0U;
        state->front_count = 0U;
        memset(&state->front_red, 0, sizeof(state->front_red));
        update_safing_gate(&state->safing_front, 0.0f, FRONT_DV_THRESHOLD_MS, dt_s, SAFING_IDLE_AX_MS2);
        update_jerk_gate(&state->jerk_front, 0.0f, dt_s, JERK_FRONT_MIN, JERK_FRONT_MAX, 0U);
        update_oscillation_gate(&state->osc_front, 0, 0U);
    }

    if (side_left_active) {
        state->side_left_duration_ticks++;
        state->side_left_red.dv_ms += accel_side_left_y * dt_s;
        state->side_left_red.energy += accel_side_left_y * accel_side_left_y * dt_s;
        update_safing_gate(&state->safing_side_left,
                           snapshot->highg_l.ay,
                           SIDE_DV_THRESHOLD_MS,
                           dt_s,
                           SAFING_IDLE_AY_MS2);
        update_jerk_gate(&state->jerk_side_left,
                         snapshot->imu.ay,
                         dt_s,
                         JERK_SIDE_MIN,
                         JERK_SIDE_MAX,
                         side_left_active);
        update_oscillation_gate(&state->osc_side_left, ay_sign, side_left_active);

        if ((state->side_left_red.dv_ms >= SIDE_DV_THRESHOLD_MS) &&
            (state->side_left_red.energy >= SIDE_RED_ENERGY_THRESHOLD)) {
            state->side_left_red.should_deploy = 1U;
        }

        if (cross_validate_side_left(snapshot)) {
            if (state->side_left_count < 0xFFU) {
                state->side_left_count++;
            }
        } else {
            state->side_left_count = 0U;
        }
    } else {
        state->side_left_duration_ticks = 0U;
        state->side_left_count = 0U;
        memset(&state->side_left_red, 0, sizeof(state->side_left_red));
        update_safing_gate(&state->safing_side_left, 0.0f, SIDE_DV_THRESHOLD_MS, dt_s, SAFING_IDLE_AY_MS2);
        update_jerk_gate(&state->jerk_side_left, 0.0f, dt_s, JERK_SIDE_MIN, JERK_SIDE_MAX, 0U);
        update_oscillation_gate(&state->osc_side_left, 0, 0U);
    }

    if (side_right_active) {
        state->side_right_duration_ticks++;
        state->side_right_red.dv_ms += accel_side_right_y * dt_s;
        state->side_right_red.energy += accel_side_right_y * accel_side_right_y * dt_s;
        update_safing_gate(&state->safing_side_right,
                           -snapshot->highg_r.ay,
                           SIDE_DV_THRESHOLD_MS,
                           dt_s,
                           SAFING_IDLE_AY_MS2);
        update_jerk_gate(&state->jerk_side_right,
                         -snapshot->imu.ay,
                         dt_s,
                         JERK_SIDE_MIN,
                         JERK_SIDE_MAX,
                         side_right_active);
        update_oscillation_gate(&state->osc_side_right, (int8_t)-ay_sign, side_right_active);

        if ((state->side_right_red.dv_ms >= SIDE_DV_THRESHOLD_MS) &&
            (state->side_right_red.energy >= SIDE_RED_ENERGY_THRESHOLD)) {
            state->side_right_red.should_deploy = 1U;
        }

        if (cross_validate_side_right(snapshot)) {
            if (state->side_right_count < 0xFFU) {
                state->side_right_count++;
            }
        } else {
            state->side_right_count = 0U;
        }
    } else {
        state->side_right_duration_ticks = 0U;
        state->side_right_count = 0U;
        memset(&state->side_right_red, 0, sizeof(state->side_right_red));
        update_safing_gate(&state->safing_side_right, 0.0f, SIDE_DV_THRESHOLD_MS, dt_s, SAFING_IDLE_AY_MS2);
        update_jerk_gate(&state->jerk_side_right, 0.0f, dt_s, JERK_SIDE_MIN, JERK_SIDE_MAX, 0U);
        update_oscillation_gate(&state->osc_side_right, 0, 0U);
    }

    if (rear_active) {
        state->rear_duration_ticks++;
        state->rear_logic.dv_ms += accel_rear_x * dt_s;
        update_safing_gate(&state->safing_rear,
                           ((snapshot->highg_l.ax + snapshot->highg_r.ax) * 0.5f),
                           REAR_DV_THRESHOLD_MS,
                           dt_s,
                           SAFING_IDLE_AX_MS2);
        update_oscillation_gate(&state->osc_rear, ax_sign, rear_active);

        if (state->rear_logic.dv_ms >= REAR_DV_THRESHOLD_MS) {
            state->rear_logic.detected = 1U;
        }

        if (cross_validate_rear(snapshot)) {
            if (state->rear_count < 0xFFU) {
                state->rear_count++;
            }
        } else {
            state->rear_count = 0U;
        }
    } else {
        state->rear_duration_ticks = 0U;
        state->rear_count = 0U;
        memset(&state->rear_logic, 0, sizeof(state->rear_logic));
        update_safing_gate(&state->safing_rear, 0.0f, REAR_DV_THRESHOLD_MS, dt_s, SAFING_IDLE_AX_MS2);
        update_oscillation_gate(&state->osc_rear, 0, 0U);
    }

    a_total_yz = sqrtf((snapshot->imu.ay * snapshot->imu.ay) + (snapshot->imu.az * snapshot->imu.az));
    alpha_eff = (f_abs(a_total_yz - G_TO_MS2) < ROLLOVER_HIGHG_FREEZE_BAND) ? ROLLOVER_FILTER_ALPHA : 1.0f;
    phi_acc_deg = atan2f(snapshot->imu.ay, snapshot->imu.az) * RAD_TO_DEG;
    state->prev_roll_angle_deg = state->roll_angle_deg;
    state->roll_angle_deg = alpha_eff * (state->roll_angle_deg + (snapshot->imu.gx * dt_s)) +
                            ((1.0f - alpha_eff) * phi_acc_deg);
    dphi_deg = state->roll_angle_deg - state->prev_roll_angle_deg;

    if (rollover_active) {
        state->rollover_duration_ticks++;
        state->rollover_phase_metric =
            ((snapshot->imu.gx * snapshot->imu.gx) / (ROLLOVER_GX_TH_DPS * ROLLOVER_GX_TH_DPS)) +
            ((state->roll_angle_deg * state->roll_angle_deg) / (ROLLOVER_PHI_CRITICAL_DEG * ROLLOVER_PHI_CRITICAL_DEG));
        update_safing_gate(&state->safing_rollover,
                           f_abs(snapshot->highg_l.ay),
                           ROLLOVER_SAFING_DV_MS,
                           dt_s,
                           SAFING_IDLE_AY_MS2);
        update_oscillation_gate(&state->osc_gyro, gx_sign, rollover_active);

        if ((dphi_deg * snapshot->imu.gx) > 0.0f && (f_abs(snapshot->imu.gx) >= ROLLOVER_ARMING_DPS)) {
            if (state->rollover_monotonic_ticks < 0xFFFFU) {
                state->rollover_monotonic_ticks++;
            }
        } else {
            state->rollover_monotonic_ticks = 0U;
        }

        if ((state->rollover_phase_metric >= 1.0f) &&
            (f_abs(snapshot->imu.ay) >= ROLLOVER_AY_TH_MS2) &&
            (f_abs(state->roll_angle_deg) >= ROLLOVER_PHI_TH_DEG)) {
            if (state->rollover_count < 0xFFU) {
                state->rollover_count++;
            }
        } else {
            state->rollover_count = 0U;
        }
    } else {
        state->rollover_duration_ticks = 0U;
        state->rollover_count = 0U;
        state->rollover_phase_metric = 0.0f;
        state->rollover_monotonic_ticks = 0U;
        update_safing_gate(&state->safing_rollover, 0.0f, ROLLOVER_SAFING_DV_MS, dt_s, SAFING_IDLE_AY_MS2);
        update_oscillation_gate(&state->osc_gyro, 0, 0U);
        if (f_abs(state->roll_angle_deg) < 1.0f) {
            state->roll_angle_deg = 0.0f;
        }
    }

    if (state->front_red.should_deploy &&
        (state->front_count >= FRONT_CONFIRM_TICKS) &&
        (state->front_duration_ticks >= PLAUSIBILITY_FRONT_MIN_TICKS) &&
        (state->front_duration_ticks <= PLAUSIBILITY_FRONT_MAX_TICKS) &&
        state->safing_front.armed &&
        state->jerk_front.is_crash &&
        !state->osc_front.is_oscillation) {
        return CRASH_EVENT_FRONT;
    }

    if (state->side_left_red.should_deploy &&
        (state->side_left_count >= SIDE_CONFIRM_TICKS) &&
        (state->side_left_duration_ticks >= PLAUSIBILITY_SIDE_MIN_TICKS) &&
        (state->side_left_duration_ticks <= PLAUSIBILITY_SIDE_MAX_TICKS) &&
        state->safing_side_left.armed &&
        state->jerk_side_left.is_crash &&
        !state->osc_side_left.is_oscillation) {
        return CRASH_EVENT_SIDE_LEFT;
    }

    if (state->side_right_red.should_deploy &&
        (state->side_right_count >= SIDE_CONFIRM_TICKS) &&
        (state->side_right_duration_ticks >= PLAUSIBILITY_SIDE_MIN_TICKS) &&
        (state->side_right_duration_ticks <= PLAUSIBILITY_SIDE_MAX_TICKS) &&
        state->safing_side_right.armed &&
        state->jerk_side_right.is_crash &&
        !state->osc_side_right.is_oscillation) {
        return CRASH_EVENT_SIDE_RIGHT;
    }

    if (state->rear_logic.detected &&
        (state->rear_count >= REAR_CONFIRM_TICKS) &&
        (state->rear_duration_ticks >= PLAUSIBILITY_REAR_MIN_TICKS) &&
        (state->rear_duration_ticks <= PLAUSIBILITY_REAR_MAX_TICKS) &&
        state->safing_rear.armed &&
        !state->osc_rear.is_oscillation) {
        return CRASH_EVENT_REAR;
    }

    if ((state->rollover_count >= ROLLOVER_CONFIRM_TICKS) &&
        (state->rollover_duration_ticks >= PLAUSIBILITY_ROLLOVER_MIN_TICKS) &&
        (state->rollover_duration_ticks <= PLAUSIBILITY_ROLLOVER_MAX_TICKS) &&
        state->safing_rollover.armed &&
        !state->osc_gyro.is_oscillation &&
        (state->rollover_monotonic_ticks >= ROLLOVER_MONOTONIC_TICKS) &&
        cross_validate_rollover(snapshot)) {
        return CRASH_EVENT_ROLLOVER;
    }

    return CRASH_EVENT_NONE;
}

static void print_decision_metrics(crash_event_t event, const decision_state_t *state)
{
    long a;
    long b;
    long c;

    switch (event) {
    case CRASH_EVENT_FRONT:
        a = (long)(state->front_red.s_m * 10000.0f);
        b = (long)(state->front_red.e_res * 1000.0f);
        c = (long)(state->safing_front.dv_ms * 100.0f);
        uart_printf("    FRONT_RED s_x1e4=%ld e_x1e3=%ld saf_x100=%ld jerk=%u osc=%u\r\n",
                    a, b, c, state->jerk_front.is_crash, state->osc_front.is_oscillation);
        break;
    case CRASH_EVENT_SIDE_LEFT:
        a = (long)(state->side_left_red.dv_ms * 100.0f);
        b = (long)(state->side_left_red.energy * 100.0f);
        c = (long)(state->safing_side_left.dv_ms * 100.0f);
        uart_printf("    SIDE_L dv_x100=%ld e_x100=%ld saf_x100=%ld jerk=%u osc=%u\r\n",
                    a, b, c, state->jerk_side_left.is_crash, state->osc_side_left.is_oscillation);
        break;
    case CRASH_EVENT_SIDE_RIGHT:
        a = (long)(state->side_right_red.dv_ms * 100.0f);
        b = (long)(state->side_right_red.energy * 100.0f);
        c = (long)(state->safing_side_right.dv_ms * 100.0f);
        uart_printf("    SIDE_R dv_x100=%ld e_x100=%ld saf_x100=%ld jerk=%u osc=%u\r\n",
                    a, b, c, state->jerk_side_right.is_crash, state->osc_side_right.is_oscillation);
        break;
    case CRASH_EVENT_REAR:
        a = (long)(state->rear_logic.dv_ms * 100.0f);
        b = (long)(state->safing_rear.dv_ms * 100.0f);
        uart_printf("    REAR dv_x100=%ld saf_x100=%ld osc=%u\r\n",
                    a, b, state->osc_rear.is_oscillation);
        break;
    case CRASH_EVENT_ROLLOVER:
        a = (long)(state->roll_angle_deg * 10.0f);
        b = (long)(state->rollover_phase_metric * 100.0f);
        c = (long)(state->safing_rollover.dv_ms * 100.0f);
        uart_printf("    ROLLOVER phi_x10=%ld F_x100=%ld monotonic=%u saf_x100=%ld\r\n",
                    a, b, state->rollover_monotonic_ticks, c);
        break;
    case CRASH_EVENT_NONE:
    case CRASH_EVENT_VISUAL:
    default:
        break;
    }
}

static uint8_t event_to_squib_mask(crash_event_t event)
{
    switch (event) {
    case CRASH_EVENT_FRONT:
        return SQUIB_CMD_FRONT_RESTRAINTS;
    case CRASH_EVENT_SIDE_LEFT:
        return SQUIB_CMD_SIDE_LEFT;
    case CRASH_EVENT_SIDE_RIGHT:
        return SQUIB_CMD_SIDE_RIGHT;
    case CRASH_EVENT_REAR:
        return SQUIB_CMD_REAR_ONLY;
    case CRASH_EVENT_ROLLOVER:
        return SQUIB_CMD_ROLLOVER_ONLY;
    case CRASH_EVENT_VISUAL:
    case CRASH_EVENT_NONE:
    default:
        return SQUIB_CMD_ALL_OFF;
    }
}

static uint8_t event_to_edr_host_id(crash_event_t event)
{
    switch (event) {
    case CRASH_EVENT_FRONT: return EDR_HOST_EVENT_FRONT;
    case CRASH_EVENT_SIDE_LEFT: return EDR_HOST_EVENT_SIDE_LEFT;
    case CRASH_EVENT_SIDE_RIGHT: return EDR_HOST_EVENT_SIDE_RIGHT;
    case CRASH_EVENT_REAR: return EDR_HOST_EVENT_REAR;
    case CRASH_EVENT_ROLLOVER: return EDR_HOST_EVENT_ROLLOVER;
    case CRASH_EVENT_VISUAL: return EDR_HOST_EVENT_VISUAL;
    case CRASH_EVENT_NONE:
    default: return 0x00;
    }
}

static const char *event_name(crash_event_t event)
{
    switch (event) {
    case CRASH_EVENT_FRONT: return "front";
    case CRASH_EVENT_SIDE_LEFT: return "side_left";
    case CRASH_EVENT_SIDE_RIGHT: return "side_right";
    case CRASH_EVENT_REAR: return "rear";
    case CRASH_EVENT_ROLLOVER: return "rollover";
    case CRASH_EVENT_VISUAL: return "visual";
    case CRASH_EVENT_NONE:
    default: return "none";
    }
}

static uint8_t perform_startup_selftest(uint8_t scenario_inputs)
{
    uint8_t sensors_ok;

    g_state = ACU_STATE_SELFTEST;
    g_last_event = CRASH_EVENT_NONE;
    g_last_squib_cmd = SQUIB_CMD_ALL_OFF;
    g_monitor_scenario = SCENARIO_IDLE;
    g_monitor_start_tick_2khz = 0U;
    g_impact_onset_tick_2khz = 0U;
    g_impact_seen = 0U;
    g_tick_2khz_missed = 0U;
    decision_reset(&g_decision);

    squib_send_command(SQUIB_CMD_ALL_OFF);
    led_all_off();
    sensorhub_release_all_cs();
    actuator_edr_release_all_cs();

    uart_puts("[BOOT] ACU self-test start\r\n");
    uart_printf("[BOOT] Inputs=0x%02X Scenario=%s\r\n", scenario_inputs, scenario_name(scenario_inputs));
    uart_puts("[BOOT] EDR disabled for this bench stage\r\n");
    /*
     * The AVR emulators in Proteus can become observable noticeably later than
     * the STM32 after a common reset. Give the slave side time to leave reset,
     * initialize GPIO/PCINT/timers and start driving its virtual buses before
     * the first self-test transactions.
     */
    HAL_Delay(100);
    sensorhub_release_all_cs();
    HAL_Delay(2);
    sensorhub_prime_link();

    sensors_ok = sensorhub_selftest_and_configure();
    if (!sensors_ok) {
        enter_fault_state(scenario_inputs, 0x00, "SensorHub self-test failed");
        return 0U;
    }

    g_state = ACU_STATE_READY;
    led_set_ready_state();
    uart_puts("[READY] Self-test complete. Press START to monitor.\r\n");
    return 1U;
}

static void enter_fault_state(uint8_t scenario_inputs, uint8_t sensor_flags, const char *reason)
{
    (void)scenario_inputs;
    (void)sensor_flags;
    squib_send_command(SQUIB_CMD_ALL_OFF);
    g_state = ACU_STATE_FAULT;
    led_set_fault_state();
    uart_printf("[FAULT] %s\r\n", reason);
}

void TIM3_IRQHandler(void)
{
    if (TIM3->SR & TIM_SR_UIF) {
        TIM3->SR &= ~TIM_SR_UIF;
        g_tick_2khz_counter++;
    }
}

void SystemClock_Config(void)
{
    RCC_OscInitTypeDef RCC_OscInitStruct = {0};
    RCC_ClkInitTypeDef RCC_ClkInitStruct = {0};

    __HAL_RCC_PWR_CLK_ENABLE();
    __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE2);

    RCC_OscInitStruct.OscillatorType = RCC_OSCILLATORTYPE_HSI;
    RCC_OscInitStruct.HSIState = RCC_HSI_ON;
    RCC_OscInitStruct.HSICalibrationValue = RCC_HSICALIBRATION_DEFAULT;
    RCC_OscInitStruct.PLL.PLLState = RCC_PLL_NONE;

    if (HAL_RCC_OscConfig(&RCC_OscInitStruct) != HAL_OK) {
        Error_Handler();
    }

    RCC_ClkInitStruct.ClockType = RCC_CLOCKTYPE_HCLK |
                                  RCC_CLOCKTYPE_SYSCLK |
                                  RCC_CLOCKTYPE_PCLK1 |
                                  RCC_CLOCKTYPE_PCLK2;
    RCC_ClkInitStruct.SYSCLKSource = RCC_SYSCLKSOURCE_HSI;
    RCC_ClkInitStruct.AHBCLKDivider = RCC_SYSCLK_DIV1;
    RCC_ClkInitStruct.APB1CLKDivider = RCC_HCLK_DIV1;
    RCC_ClkInitStruct.APB2CLKDivider = RCC_HCLK_DIV1;

    if (HAL_RCC_ClockConfig(&RCC_ClkInitStruct, FLASH_LATENCY_0) != HAL_OK) {
        Error_Handler();
    }
}

void Error_Handler(void)
{
    while (1) {
        HAL_GPIO_TogglePin(LED_FAULT_GPIO_Port, LED_FAULT_Pin);
        for (volatile uint32_t i = 0; i < 200000U; i++) {
            __NOP();
        }
    }
}

#ifdef USE_FULL_ASSERT
void assert_failed(uint8_t *file, uint32_t line)
{
    (void)file;
    (void)line;
    Error_Handler();
}
#endif
